def flatMapSharedInt(cnt: Int, fi: Traversers.IntToRefFn[FBase]): FBase = {
  val inr0 = fi.apply(0)
  val l0 = inr0.length
  if (l0 >= 32) flatMapSegsInt(cnt, inr0, l0, fi) else flatMapFlatInt(cnt, inr0, l0, fi)
}

