def flatMapFlatInt(cnt: Int, inr0: FBase, l0: Int, fi: Traversers.IntToRefFn[FBase]): FBase = {
  val est = { val e = cnt * l0; if (e < 8) 8 else e }
  var out: Array[Int] = new Array[Int](est)
  inr0 match { case lf: IntArr => System.arraycopy(lf.arr, 0, out, 0, l0); case o: IntOne => out(0) = o.elem; case _ => flatMapCopyOneInt(inr0, out, 0) }
  var off = l0
  var i = 1
  while (i < cnt) {
    val inr = fi.apply(i)
    val ln = inr.length
    out = ensureCapInt(out, off + ln)
    inr match {
      case lf: IntArr => {
        if (ln <= 8) { val ia = lf.arr; var c = 0; while (c < ln) { out(off + c) = ia(c); c += 1 } }
        else System.arraycopy(lf.arr, 0, out, off, ln)
      }
      case o: IntOne => out(off) = o.elem
      case _ => flatMapCopyOneInt(inr, out, off)
    }
    off += ln
    i += 1
  }
  if (off == 0) Empty.INSTANCE else if (off == 1) new IntOne(out(0)) else new IntArr(out, off)
}

