def filterLeafInt(xs: FBase, p: Traversers.IntPred): FBase = {
  xs match {
    case e: Empty => Empty.INSTANCE
    case o: IntOne => if (p.apply(o.elem)) xs else Empty.INSTANCE
    case leaf: IntArr => {
      val a = leaf.arr
      val n = leaf.length
      val out = new Array[Int](n)
      var i = 0
      var o = 0
      while (i < n) {
        val e = a(i)
        out(o) = e
        o += (if (p.apply(e)) 1 else 0)
        i += 1
      }
      if (o == n) xs else trimLeafInt(out, o, n)
    } case s: SliceNode if s.base.isInstanceOf[IntArr] => {
      val a = s.base.asInstanceOf[IntArr].arr
      val so = s.offset
      val n = s.length
      val out = new Array[Int](n)
      var i = 0
      var o = 0
      while (i < n) {
        val e = a(so + i)
        out(o) = e
        o += (if (p.apply(e)) 1 else 0)
        i += 1
      }
      if (o == n) xs else trimLeafInt(out, o, n)
    } case _ => {
      val n = xs.length
      val out = new Array[Int](n)
      val o = Traversers.buildFilteredInt(xs, out, 0, p)
      trimLeafInt(out, o, n)
    }
  }
}

