static <RO> int buildFwdIntRef(FBase root, Object[] out, int o, IntToRefFn<RO> f) {
    FBase cur = root;
    FBase[] stack = null;
    int[] tail = null;
    boolean[] isTail = null;
    int sp = 0;
    while (cur != null) {
        FBase next = null;
        if (cur instanceof IntArr leaf) {
            {
                int[] a = leaf.arr;
                int i = 0;
                int end = leaf.length;
                while (i < end) {
                    out[o] = f.apply(a[i]);
                    o += 1;
                    i += 1;
                }
            }
        } else if (cur instanceof IntFlatMap fm) {
            int[][] fsegs = fm.segs;
            int[] foffs = fm.offs;
            for (int fsi = 0; fsi < fsegs.length; fsi++) {
                {
                    int[] a = fsegs[fsi];
                    int i = 0;
                    int end = foffs[fsi + 1] - foffs[fsi];
                    while (i < end) {
                        out[o] = f.apply(a[i]);
                        o += 1;
                        i += 1;
                    }
                }
            }
        } else if (cur instanceof IntOne one) {
            out[o] = f.apply(one.elem);
            o += 1;
        } else if (cur instanceof IntPrepend p) {
            out[o] = f.apply(p.elem);
            o += 1;
            next = p.base;
        } else if (cur instanceof IntAppend ap) {
            if (stack == null) {
                stack = new FBase[16];
            } else if (sp == stack.length) {
                int nl = sp * 2;
                stack = java.util.Arrays.copyOf(stack, nl);
                if (isTail != null) {
                    tail = java.util.Arrays.copyOf(tail, nl);
                    isTail = java.util.Arrays.copyOf(isTail, nl);
                }
            }
            if (isTail == null) {
                tail = new int[stack.length];
                isTail = new boolean[stack.length];
            }
            tail[sp] = ap.elem;
            isTail[sp] = true;
            sp += 1;
            next = ap.base;
        } else if (cur instanceof Concat c) {
            if (stack == null) {
                stack = new FBase[16];
            } else if (sp == stack.length) {
                int nl = sp * 2;
                stack = java.util.Arrays.copyOf(stack, nl);
                if (isTail != null) {
                    tail = java.util.Arrays.copyOf(tail, nl);
                    isTail = java.util.Arrays.copyOf(isTail, nl);
                }
            }
            if (isTail != null) {
                isTail[sp] = false;
            }
            stack[sp] = c.right;
            sp += 1;
            next = c.left;
        } else if (cur instanceof ReverseNode rev) {
            o = buildBwdIntRef(rev.base, out, o, f);
        } else if (cur instanceof SliceNode s) {
            int so = s.offset;
            int sn = s.length;
            if (s.base instanceof IntArr lf) {
                {
                    int[] a = lf.arr;
                    int i = so;
                    int end = i + (sn);
                    while (i < end) {
                        out[o] = f.apply(a[i]);
                        o += 1;
                        i += 1;
                    }
                }
            } else {
                o = buildWindowFwdIntRef(s.base, so, sn, out, o, f);
            }
        } else if (cur instanceof IntPad pad) {
            int bl = pad.base.length;
            int pf = pad.filler;
            int pn = pad.length;
            if (pad.base instanceof IntArr lf) {
                {
                    int[] a = lf.arr;
                    int i = 0;
                    int end = i + (bl);
                    while (i < end) {
                        out[o] = f.apply(a[i]);
                        o += 1;
                        i += 1;
                    }
                }
            } else {
                o = buildWindowFwdIntRef(pad.base, 0, bl, out, o, f);
            }
            int pj = bl;
            while (pj < pn) {
                out[o] = f.apply(pf);
                o += 1;
                pj += 1;
            }
        } else if (cur instanceof IntUpdated u) {
            int ui = u.index;
            int ul = u.length;
