def containsLeafInt(node0: SBase, e: Int): Boolean = {
  var node: SBase = node0
  var flip = false
  while (true) {
    node match {
      case _: SEmpty => return flip
      case o: SIntOne => return (o.elem == e) ^ flip
      case s: SIntSorted => {
        val a = s.arr
        var i = 0
        while (i < a.length) {
          val v = a(i)
          if ((v == e)) return !flip
          if ((e < v)) return flip
          i += 1
        }
        return flip
      }
      case u: SUnion => if (containsLeafInt(u.right, e)) return !flip else node = u.left
      case n: SInter => if (!containsLeafInt(n.right, e)) return flip else node = n.left
      case d: SDiff => if (containsLeafInt(d.right, e)) return flip else node = d.left
      case x: SXor => x.left match { case _: SView => { flip ^= containsLeafInt(x.right, e); node = x.left }; case l => return (containsLeafInt(l, e) ^ containsLeafInt(x.right, e)) ^ flip }
      case h: SIntHash => {
        val arr = h.arr
        val idx = h.index
        var slot = (mixInt(e)) & (idx.length - 1)
        var res = false; var go = true
        while (go) {
          val p = idx(slot)
          if (p == -1) go = false
          else if ((arr(p) == e)) { res = true; go = false }
          else slot = (slot + 1) & (idx.length - 1)
        }
        return res ^ flip
      }
      case b: SIntBitmap => { val i = e - b.base; return (i >= 0 && (i >>> 6) < b.words.length && (b.words(i >>> 6) >>> i & 1L) != 0L) ^ flip }
      case r: SIntRange => return (r.lo <= e && e <= r.hi) ^ flip
      case c: SComplement => { flip = !flip; node = c.inner }
      case _ => return flip
    }
  }
  false
}

