def mergeUnionRef(aA: Array[Object], aH: Array[Int], bA: Array[Object], bH: Array[Int]): SBase = {
  val na = aA.length; val nb = bA.length
  val outA = new Array[Object](na + nb)
  val outH = new Array[Int](na + nb)
  var i = 0; var j = 0; var w = 0
  while (i < na && j < nb) {
    val ha = aH(i); val hb = bH(j)
    if (ha < hb) { outA(w) = aA(i); outH(w) = ha; w += 1; i += 1 }
    else if (ha > hb) { outA(w) = bA(j); outH(w) = hb; w += 1; j += 1 }
    else {
      var ie = i; while (ie < na && aH(ie) == ha) ie += 1
      var je = j; while (je < nb && bH(je) == hb) je += 1
      var k = i; while (k < ie) { outA(w) = aA(k); outH(w) = ha; w += 1; k += 1 }
      k = j
      while (k < je) {
        val v = bA(k)
        var found = false; var m = i
        while (m < ie && !found) { if (aA(m).equals(v)) found = true; m += 1 }
        if (!found) { outA(w) = v; outH(w) = hb; w += 1 }
        k += 1
      }
      i = ie; j = je
    }
  }
  while (i < na) { outA(w) = aA(i); outH(w) = aH(i); w += 1; i += 1 }
  while (j < nb) { outA(w) = bA(j); outH(w) = bH(j); w += 1; j += 1 }
  wrapRef(java.util.Arrays.copyOf(outA, w), java.util.Arrays.copyOf(outH, w))
}

