def buildSortedInt(raw: Array[Int], len: Int, owned: Boolean): SBase = {
  if (len == 0) return SEmpty.INSTANCE
  var mn = raw(0); var mx = raw(0); var di = 1
  while (di < len) { val v = raw(di); if (v < mn) mn = v; if (v > mx) mx = v; di += 1 }
  val dspan = mx.toLong - mn.toLong + 1L
  if (len >= 2 && dspan <= 64L * len && dspan <= (1L << 20)) {
    val dbase = (mn >> 6) << 6
    val dnw = ((mx - dbase) >>> 6) + 1
    val dwords = new Array[Long](dnw)
    var bi = 0; while (bi < len) { val bb = raw(bi) - dbase; dwords(bb >>> 6) |= (1L << bb); bi += 1 }
    var dcard = 0; var dwi = 0; while (dwi < dnw) { dcard += java.lang.Long.bitCount(dwords(dwi)); dwi += 1 }
    return new SIntBitmap(dbase, dcard, dwords)
  }
  val a = if (owned) raw else java.util.Arrays.copyOf(raw, len)
  java.util.Arrays.sort(a, 0, len)
  var w = 1
  var i = 1
  while (i < len) {
    if ((a(i) != a(i - 1))) {
      a(w) = a(i)
      w += 1
    }
    i += 1
  }
  if (w == 1) new SIntOne(a(0))
  else wrapInt(java.util.Arrays.copyOf(a, w))
}

